const ASSETS={"/index.html":{"type":"text/html; charset=utf-8","body":"<!doctype html><html lang=\"zh-CN\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>拾忆 · 你的私人记忆空间</title><meta name=\"description\" content=\"随手记录文字、图片、链接与声音，留待需要时找回。\"><link rel=\"icon\" href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 40 40'%3E%3Crect width='40' height='40' rx='12' fill='%232b3955'/%3E%3Cpath d='M12 12h16v16H12z' fill='none' stroke='white' stroke-width='3'/%3E%3C/svg%3E\"><link rel=\"stylesheet\" href=\"/style.css\"></head><body>\n<aside class=\"rail\"><button class=\"logo\" id=\"home\" aria-label=\"回到首页\">▣</button><nav><button data-view=\"library\" aria-label=\"全部记忆\">▤<span>记忆</span></button><button data-view=\"topics\" aria-label=\"主题集合\">▦<span>主题</span></button><button data-view=\"tasks\" aria-label=\"行动提醒\">◷<span>行动</span></button><button data-view=\"trash\" aria-label=\"回收站\">⌫<span>回收站</span></button></nav><button id=\"account\" class=\"account\" aria-label=\"账号与 AI 设置\">我</button></aside>\n<main><header><a href=\"/\" class=\"wordmark\">拾忆 <span>SHIYI</span></a><span class=\"headernote\" id=\"connection\">连接你的空间…</span></header><section class=\"quiet\"><div class=\"greeting\"><p class=\"eyebrow\">A LITTLE SPACE FOR YOUR MIND</p><h1>先放在这里。<br><span>需要时，再想起来。</span></h1><p>一个念头，一段对话，或一句不想忘记的话。</p></div><div class=\"composer\"><div class=\"modebar\" role=\"group\" aria-label=\"收集方式\"><button class=\"active\" data-mode=\"text\">文字 / 链接</button><button data-mode=\"image\">图片</button><button data-mode=\"audio\">声音</button></div><textarea id=\"thought\" aria-label=\"要保存的内容\" placeholder=\"随手写点什么，也可以粘贴链接…\" maxlength=\"20000\"></textarea><div id=\"attachmentArea\" hidden><label class=\"filepick\" id=\"filepick\"><span id=\"filelabel\">选择图片，或拖到这里</span><input id=\"file\" type=\"file\" accept=\"image/png,image/jpeg,image/webp\" hidden></label><div id=\"attachmentPreview\"></div></div><div id=\"recordArea\" hidden><button id=\"record\" class=\"record\">● 开始录音</button><span id=\"recordState\">最长 2 分钟，可先试听再保存</span></div><div class=\"composerfoot\"><span id=\"savehint\">链接会被保存，只有点击时才打开。</span><button id=\"save\" class=\"primary\">收好 ↗</button></div></div><p class=\"privacy\">资料保存在你的私有账号空间 · AI 仅在你点击处理时使用</p><div class=\"searchline\"><span>⌕</span><input id=\"search\" aria-label=\"找回记忆\" placeholder=\"记得哪个词？找一找…\"><kbd>⌘ K</kbd></div><div id=\"homeResults\" hidden></div><div class=\"recentline\"><button data-view=\"library\">打开记忆库 <span id=\"total\">0</span> ↗</button><button id=\"trydemo\">看看整理后的样子</button></div><div id=\"banner\" role=\"status\"></div></section><footer><span>留住内容，也留住当时的想法。</span><button id=\"aboutai\">AI 能帮我做什么？</button></footer></main>\n<dialog id=\"panel\" class=\"panel\"><div class=\"paneltop\"><div><p class=\"eyebrow\">YOUR MEMORY SPACE</p><h2 id=\"paneltitle\">全部记忆</h2></div><button data-close=\"panel\" aria-label=\"关闭侧栏\">×</button></div><div id=\"panelbody\"></div></dialog><dialog id=\"detail\"><div class=\"modalhead\"><h2>这段记忆</h2><button data-close=\"detail\" aria-label=\"关闭详情\">×</button></div><div id=\"detailbody\"></div></dialog><dialog id=\"confirm\"><div class=\"modalhead\"><h2>移到回收站？</h2><button data-close=\"confirm\" aria-label=\"取消删除\">×</button></div><p>它将不再出现在搜索和行动中。你可以在回收站恢复；原始文件仍保留。</p><div class=\"actions\"><button data-close=\"confirm\">保留</button><button id=\"confirmDelete\" class=\"danger\">移到回收站</button></div></dialog><dialog id=\"accountDialog\"><div class=\"modalhead\"><h2>账号与 AI</h2><button data-close=\"accountDialog\" aria-label=\"关闭账号设置\">×</button></div><div id=\"accountbody\"></div></dialog><div id=\"toast\" role=\"status\"></div><script src=\"/app.js\"></script></body></html>\n"},"/style.css":{"type":"text/css; charset=utf-8","body":":root{--ink:#29364d;--soft:#858c98;--line:#e9ebee;--accent:#496458}*{box-sizing:border-box}[hidden]{display:none!important}body{margin:0;background:white;color:var(--ink);font:16px/1.7 -apple-system,BlinkMacSystemFont,\"PingFang SC\",\"Microsoft YaHei\",sans-serif}button,input,textarea,select{font:inherit}button{cursor:pointer;border:0;background:transparent;color:inherit;border-radius:8px;padding:8px 12px}button:hover{background:#f0f3f2}button:disabled{opacity:.45;cursor:wait}button:focus-visible,a:focus-visible{outline:2px solid #7e9e91;outline-offset:4px}input,textarea,select{color:var(--ink)}a{color:var(--accent)}.rail{width:82px;position:fixed;inset:0 auto 0 0;border-right:1px solid var(--line);background:#fcfcfc;display:flex;align-items:center;flex-direction:column;padding:26px 10px;z-index:2}.logo{font-size:30px;padding:0;width:48px;height:48px}.rail nav{display:grid;gap:22px;margin-top:58px}.rail nav button{font-size:24px;line-height:1.1;width:60px;color:#858e9a}.rail nav span{display:block;font-size:12px;margin-top:8px;letter-spacing:1px}.rail nav button:hover{color:var(--accent)}.account{margin-top:auto;width:36px;height:36px;border:1px solid #d9dfe0;border-radius:50%;font-size:13px;padding:4px}main{margin-left:82px;min-height:100vh;display:flex;flex-direction:column}header{height:90px;display:flex;align-items:center;justify-content:space-between;padding:0 52px}.wordmark{text-decoration:none;color:var(--ink);font-weight:650;font-size:20px;letter-spacing:3px}.wordmark span{font-size:12px;font-weight:400;letter-spacing:3px;color:#a5abb2;margin-left:12px}.headernote{font-size:12px;color:#9ba1a9}.quiet{width:min(650px,calc(100% - 70px));margin:50px auto 80px}.eyebrow{font-size:12px;color:#a2aaa7;letter-spacing:2.8px;margin:0 0 22px}.greeting{margin-bottom:38px}h1{font-size:40px;font-weight:500;line-height:1.55;letter-spacing:1px;margin:0}h1 span{color:#9aa39f}.greeting>p:last-child{font-size:14px;color:#939b96;margin-top:18px}.composer{border:1px solid #e1e6e3;border-radius:16px;padding:16px 20px 14px;box-shadow:0 10px 35px #203c2604}.modebar{display:flex;gap:6px}.modebar button{font-size:14px;color:#838b85;padding:5px 11px}.modebar button.active{background:#eef3ef;color:var(--accent)}textarea{display:block;width:100%;min-height:108px;resize:vertical;border:0;outline:0;line-height:1.8;padding:17px 7px;background:transparent;font-size:16px}textarea::placeholder,input::placeholder{color:#a0a8a1}.composer:focus-within{border-color:#9aae9f}.composerfoot{display:flex;align-items:center;gap:20px;justify-content:space-between;padding-top:10px}.composerfoot>span{color:#8e9890;font-size:12px}.primary{background:#344d40;color:white;padding:9px 20px;border-radius:9px;white-space:nowrap}.primary:hover{background:#243b2e}.privacy{font-size:12px;color:#939f96;margin:13px 2px 36px}.searchline{display:flex;align-items:center;border-bottom:1px solid var(--line);padding:13px 3px;gap:13px}.searchline>span{font-size:24px;color:#a1aaa4}.searchline input{flex:1;width:0;border:0;outline:0;background:transparent;font-size:16px}kbd{font:12px sans-serif;color:#a1aaa4}.recentline{display:flex;justify-content:space-between;margin-top:16px}.recentline button{font-size:13px;color:#7e8e82;padding:7px 0}.recentline span{font-size:12px;padding:1px 6px;background:#f3f5f3;margin:0 6px;border-radius:4px}footer{margin-top:auto;padding:25px 52px;display:flex;justify-content:space-between;font-size:12px;color:#9ca69e}footer button{font-size:12px;color:#8e9891;padding:0}.filepick{display:block;padding:22px;text-align:center;border:1px dashed #cdd7d0;background:#fafcfa;cursor:pointer;border-radius:10px;font-size:14px;color:#839187}.filepick:hover{border-color:var(--accent)}#attachmentPreview{margin-top:10px}#attachmentPreview img{max-width:100%;max-height:200px;border-radius:8px;display:block;margin:auto}audio{width:100%;margin-top:10px}#recordArea{display:flex;align-items:center;gap:12px;margin:15px 0}.record{color:#9c4f4f;background:#fbf1f1;font-size:14px}#recordState{font-size:12px;color:#919a93}.muted{color:#829086;font-size:14px}.error{color:#b15858;font-size:14px}.badge{display:inline-block;font-size:12px;padding:2px 7px;background:#f2f5f2;color:#6f8374;border-radius:5px}.pending{color:#a48353;background:#faf6ed}dialog{border:1px solid #e7eae7;border-radius:15px;width:min(560px,calc(100% - 28px));max-height:90vh;padding:26px;color:var(--ink);box-shadow:0 20px 100px #172d2520}dialog::backdrop{background:#25352d25;backdrop-filter:blur(4px)}.panel{height:100dvh;max-height:100dvh;width:min(540px,100vw);margin:0 0 0 auto;border-radius:0;border-top:0;border-bottom:0;padding:32px}.paneltop,.modalhead{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:24px}.paneltop .eyebrow{margin-bottom:6px}.paneltop h2,.modalhead h2{font-size:22px;font-weight:500;margin:0}.paneltop button,.modalhead button{font-size:24px;line-height:1;padding:7px}.itemrow{display:flex;align-items:center;gap:12px;padding:18px 0;border-bottom:1px solid var(--line)}.itemicon{width:37px;height:40px;display:grid;place-items:center;background:#f4f6f4;color:#8a9a8f;font-size:20px;border-radius:8px;flex-shrink:0}.rowopen{text-align:left;flex:1;min-width:0;padding:0}.rowopen strong{font-size:15px;font-weight:500;display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.rowopen p{font-size:12px;color:#8a978e;margin:5px 0 0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.smallbtn{font-size:13px;color:#829087;padding:6px}.rowopen:hover{background:transparent;color:var(--accent)}.empty{padding:48px 10px;text-align:center;color:#8c998f}.empty strong{font-weight:400;font-size:17px}.empty p{font-size:14px}.panelsearch{width:100%;padding:10px 12px;border:1px solid var(--line);border-radius:9px;outline:0;margin-bottom:10px}.filters{display:flex;gap:6px;flex-wrap:wrap;margin:14px 0}.filters button{font-size:13px;color:#879189;padding:4px 9px}.filters button.active{background:#edf2ed;color:#344d40}.field{display:block;font-size:14px;margin:19px 0;color:#6a796e}.field input,.field select,.field textarea{display:block;width:100%;padding:10px 12px;border:1px solid #e0e6e0;border-radius:8px;margin-top:7px;font-size:15px;background:white;outline:0}.field textarea{min-height:100px}.media{max-width:100%;max-height:360px;display:block;margin:15px auto;border-radius:8px}.summary{font-size:15px;line-height:1.9;padding:13px 0;white-space:pre-wrap}.source{white-space:pre-wrap;font-size:14px;color:#7d877f;border-left:2px solid #d9e4db;padding-left:14px;max-height:250px;overflow:auto;margin:16px 0;word-break:break-word}.links{margin:15px 0}.linkrow{padding:12px;border:1px solid var(--line);border-radius:8px;margin:8px 0;display:flex;gap:10px;align-items:center}.linkrow a{word-break:break-all;font-size:14px;flex:1}.actions{display:flex;gap:10px;justify-content:flex-end;margin-top:22px;flex-wrap:wrap}.danger{color:#a95b55;background:#fcf2f0}.full{width:100%;margin-top:12px}.related{display:block;text-align:left;width:100%;font-size:14px;border-bottom:1px solid var(--line);padding:12px 0}.divider{height:1px;background:var(--line);margin:22px 0}.task{padding:19px 0;border-bottom:1px solid var(--line)}.task h3{font-size:16px;font-weight:500;margin:7px 0}.task p{font-size:14px;color:#929c94}.task button{font-size:14px}.topicrow{display:flex;justify-content:space-between;align-items:center;width:100%;padding:18px 5px;border-bottom:1px solid var(--line);text-align:left}.topicrow span{color:#a2a9a3;font-size:12px}.answer{white-space:pre-wrap;font-size:15px;line-height:1.9;margin:16px 0}.accountcard{padding:17px 0;border-bottom:1px solid var(--line)}.accountcard b{display:block;font-size:15px;font-weight:500}.accountcard p{font-size:14px;color:#8e9890;word-break:break-word}.accountcard a{font-size:14px}.aiNote{font-size:12px;color:#9f9482;margin:12px 0}.check{display:flex;gap:8px;align-items:flex-start;font-size:13px;margin-top:18px}.check input{margin-top:5px}.signin{display:block;text-align:center;text-decoration:none;padding:12px;border-radius:9px;background:#344d40;color:white}#toast{display:none;position:fixed;bottom:25px;left:50%;transform:translateX(-50%);background:#344d40;color:white;border-radius:10px;padding:12px 20px;font-size:14px;z-index:9;max-width:90vw}#banner{font-size:13px;color:#929a95;margin-top:18px}.demolabel{font-size:12px;color:#a18e73;background:#faf5ec;padding:10px 14px;border-radius:8px} @media(min-width:1450px){.quiet{margin-top:80px}}@media(max-width:700px){.rail{width:61px;padding:20px 3px}.rail nav{gap:19px;margin-top:35px}.rail nav button{width:52px;font-size:22px}main{margin-left:61px}header{height:74px;padding:0 23px}.headernote{font-size:12px;max-width:130px;text-align:right}.wordmark span{display:none}.quiet{width:calc(100% - 42px);margin:34px auto 45px}h1{font-size:29px}.eyebrow{font-size:10px;letter-spacing:1.8px}.greeting>p:last-child{font-size:14px}.greeting{margin-bottom:30px}.composer{padding:12px}.composerfoot>span{font-size:12px;line-height:1.5}.primary{padding:8px 13px;font-size:14px}.modebar button{font-size:13px;padding:4px 8px}textarea{font-size:16px}footer{padding:15px 22px}footer>span{display:none}.panel{padding:23px}.recentline button{font-size:12px}.searchline input{font-size:16px}#recordArea{flex-wrap:wrap}.composerfoot{gap:9px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}\n"},"/app.js":{"type":"text/javascript; charset=utf-8","body":"const $=id=>document.getElementById(id);\nconst esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst modes=['只收藏','稍后看或试','学习','待行动'];\nconst icons={text:'≡',link:'↗',image:'▧',audio:'♪'};\nconst types={text:'文字',link:'链接',image:'图片',audio:'录音'};\nlet records=[],me=null,mode='text',attachment=null,attachmentURL=null,view='library',filter='全部',panelQuery='',recorder=null,stream=null,recordTimer=null,recordClock=null,saving=false;\nconst demo=[{id:'demo1',kind:'image',title:'日语自他动词：開く与開ける',text:'ドアが開く。门开了。\\nドアを開ける。把门打开。',summary:'用同一场景区分自发变化和对对象的动作。',topic:'日语学习',intent:'学习',tags:['自他动词','日语'],status:'示例',links:[],createdAt:'2026-09-14',demo:true},{id:'demo2',kind:'image',title:'和朋友约好周末逛书店',text:'朋友：周末一起逛书店？\\n我：好呀，具体时间再定。',summary:'有见面意向，时间未定。保留约定，不推测截止日期。',topic:'生活约定',intent:'只收藏',tags:['聊天','书店'],status:'示例',links:[],createdAt:'2026-09-14',demo:true},{id:'demo3',kind:'text',title:'日语助词「が」和「を」',text:'「が」标记主语。「を」常标记动作的宾语。',summary:'和自他动词一起理解。',topic:'日语学习',intent:'只收藏',tags:['日语','助词'],status:'示例',links:[],createdAt:'2026-09-14',demo:true}];\nfunction notify(text){$('toast').textContent=text;$('toast').style.display='block';clearTimeout(window.toasting);window.toasting=setTimeout(()=>$('toast').style.display='none',4000)}\nfunction show(id){if(!$(id).open)$(id).showModal()}\nasync function api(path,options={}){const res=await fetch('/api/'+path,options);let data;try{data=await res.json()}catch{throw new Error('服务暂时不可用，请稍后重试')}if(!res.ok)throw new Error(data.error||'操作失败，请重试');return data}\nasync function refresh(){const data=await api('memories');records=data.items;$('total').textContent=records.filter(r=>!r.deletedAt).length;renderSearch();if($('panel').open)renderPanel()}\nasync function init(){try{me=await api('me');$('connection').textContent='私人空间 · 已登录';$('banner').textContent=me.aiEnabled?'AI 已就绪。你可以在详情中主动识别和归纳。':'AI 尚未启用。可先保存内容、录音与链接，稍后再识别。';await refresh()}catch(e){$('connection').textContent='空间尚未连接';$('banner').textContent=e.message}}\nfunction match(r,q){return !q||[r.title,r.text,r.extractedText,r.transcript,r.summary,r.topic,...(r.tags||[]),...(r.links||[])].join(' ').toLowerCase().includes(q.trim().toLowerCase())}\nfunction row(r){return `<div class=\"itemrow\"><span class=\"itemicon\">${icons[r.kind]||'≡'}</span><button class=\"rowopen\" data-open=\"${esc(r.id)}\"><strong>${esc(r.title)}</strong><p>${esc(types[r.kind])} · ${esc(r.topic)} · ${esc(r.status)}${r.summary?' · '+esc(r.summary):''}</p></button>${r.deletedAt?`<button class=\"smallbtn\" data-restore=\"${r.id}\">恢复</button>`:`<button class=\"smallbtn\" data-delete=\"${r.id}\" aria-label=\"删除 ${esc(r.title)}\">删除</button>`}</div>`}\nfunction renderSearch(){const q=$('search').value.trim();$('homeResults').hidden=!q;if(!q)return;const found=records.filter(r=>!r.deletedAt&&match(r,q));$('homeResults').innerHTML=found.slice(0,5).map(row).join('')+`<p class=\"muted\">${found.length?`找到 ${found.length} 条；按内容关键词匹配。`:'没有找到。尚未识别的图片可补充文字说明后检索。'}</p><button class=\"smallbtn\" id=\"askSearch\">✦ 根据资料回答这个问题</button>`;$('askSearch').onclick=()=>ask(q,found.map(r=>r.id))}\nfunction openPanel(v){view=v;filter='全部';panelQuery='';renderPanel();show('panel')}\nfunction renderPanel(){const names={library:'全部记忆',topics:'主题集合',tasks:'行动提醒',trash:'回收站',demo:'整理后的样子'};$('paneltitle').textContent=names[view];const active=records.filter(r=>!r.deletedAt);\nif(view==='demo'){$('panelbody').innerHTML='<p class=\"demolabel\">以下为合成示例，不会混入你的真实资料。</p>'+demo.map(r=>`<div class=\"itemrow\"><span class=\"itemicon\">${icons[r.kind]}</span><button class=\"rowopen\" data-open=\"${r.id}\"><strong>${r.title}</strong><p>${r.topic} · ${r.summary}</p></button></div>`).join('');return}\nif(view==='topics'){const ts=[...new Set(active.map(r=>r.topic))];$('panelbody').innerHTML=ts.length?ts.map(t=>`<button class=\"topicrow\" data-topic=\"${esc(t)}\">${esc(t)}<span>${active.filter(r=>r.topic===t).length} 条 ↗</span></button>`).join(''):'<div class=\"empty\"><strong>主题会在这里聚合</strong><p>保存资料后可手动设置主题，或启用 AI 整理。</p></div>';return}\nif(view==='tasks'){const tasks=active.filter(r=>r.reminder);$('panelbody').innerHTML='<p class=\"aiNote\">此版保存行动计划，尚不发送后台通知。</p>'+ (tasks.length?tasks.map(r=>`<article class=\"task\"><span class=\"badge\">${esc(r.reminder.status)}</span><h3>${esc(r.title)}</h3><p>${esc(r.reminder.when.replace('T',' '))} · ${esc(r.reminder.priority)} · ${esc(r.reminder.frequency)}</p><button data-open=\"${r.id}\">查看资料</button>${r.reminder.status!=='已完成'?`<button data-task=\"${r.id}\" data-status=\"已完成\">完成</button><button data-task=\"${r.id}\" data-status=\"delay\">延后一天</button><button data-task=\"${r.id}\" data-status=\"${r.reminder.status==='已暂停'?'进行中':'已暂停'}\">${r.reminder.status==='已暂停'?'恢复':'暂停'}</button>`:''}<button data-task=\"${r.id}\" data-status=\"cancel\">取消计划</button></article>`).join(''):'<div class=\"empty\"><strong>不用把每条收藏都变成任务</strong><p>打开一份资料，确认后再安排跟进。</p></div>');return}\nconst list=records.filter(r=>view==='trash'?!!r.deletedAt:!r.deletedAt).filter(r=>match(r,panelQuery)&&(filter==='全部'||r.kind===filter));$('panelbody').innerHTML=(view==='trash'?'<p class=\"muted\">移入这里的资料已从搜索与行动中隐藏，可恢复。</p>':`<input class=\"panelsearch\" id=\"panelSearch\" aria-label=\"搜索资料库\" placeholder=\"搜索内容、备注或链接\" value=\"${esc(panelQuery)}\"><div class=\"filters\">${[['全部','全部'],['text','文字'],['image','图片'],['link','链接'],['audio','录音']].map(([v,n])=>`<button class=\"${filter===v?'active':''}\" data-filter=\"${v}\">${n}</button>`).join('')}</div>`)+`<div id=\"rows\">${list.length?list.map(row).join(''):'<div class=\"empty\"><strong>这里还很安静</strong><p>从首页保存第一段记忆，或换个关键词。</p></div>'}</div>`;if($('panelSearch'))$('panelSearch').oninput=e=>{panelQuery=e.target.value;const list=records.filter(r=>!r.deletedAt&&match(r,panelQuery)&&(filter==='全部'||r.kind===filter));$('rows').innerHTML=list.map(row).join('')||'<p class=\"muted\">没有匹配内容</p>'}}\nfunction get(id){return records.find(r=>r.id===id)||demo.find(r=>r.id===id)}\nasync function patch(id,body){const r=await api('memories/'+id,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify(body)});records=records.map(x=>x.id===id?r:x);$('total').textContent=records.filter(x=>!x.deletedAt).length;renderSearch();if($('panel').open)renderPanel();return r}\nfunction openDetail(id){const r=get(id);if(!r)return;if(r.deletedAt){notify('请先从回收站恢复这份资料');return}const related=(r.demo?demo:records).filter(x=>x.id!==r.id&&!x.deletedAt&&r.topic!=='未分类'&&x.topic===r.topic).slice(0,5);$('detailbody').innerHTML=`${r.demo?'<p class=\"demolabel\">合成示例 · 用来说明整理结果</p>':''}<span class=\"badge ${r.status!=='已整理'?'pending':''}\">${esc(r.status)}</span>${r.hasFile?(r.kind==='image'?`<img class=\"media\" src=\"/api/memories/${r.id}/file\" alt=\"保存的原始图片\">`:`<audio controls src=\"/api/memories/${r.id}/file\"></audio>`):''}<label class=\"field\">内容标题<input id=\"editTitle\" maxlength=\"100\" value=\"${esc(r.title)}\"></label>${r.summary?`<div class=\"summary\">${esc(r.summary)}</div>`:'<p class=\"muted\">还没有内容摘要。可先补充说明，启用 AI 后再识别。</p>'}${r.extractedText||r.transcript?`<details><summary>查看识别原文</summary><div class=\"source\">${esc(r.transcript||r.extractedText)}</div></details>`:''}<label class=\"field\">原始文字 / 我的备注<textarea id=\"editText\" maxlength=\"20000\">${esc(r.text)}</textarea></label>${(r.links||[]).map((link,i)=>`<div class=\"linkrow\"><a href=\"${esc(link)}\" target=\"_blank\" rel=\"noopener noreferrer\">${esc(link)} ↗</a><button class=\"smallbtn\" data-copy=\"${i}\" data-record=\"${r.id}\">复制</button></div>`).join('')}<label class=\"field\">主题<input id=\"editTopic\" maxlength=\"60\" value=\"${esc(r.topic)}\"></label><label class=\"field\">保存意图<select id=\"editIntent\">${modes.map(m=>`<option ${r.intent===m?'selected':''}>${m}</option>`).join('')}</select></label>${r.suggestedIntent?`<p class=\"muted\">AI 建议：${esc(r.suggestedIntent)}。保存意图仍由你决定。</p>`:''}${related.length?'<div class=\"divider\"></div><p class=\"muted\">同主题资料 · 按相同主题关联</p>'+related.map(x=>`<button class=\"related\" data-open=\"${x.id}\">${esc(x.title)} ↗</button>`).join(''):''}${!r.demo?`<div class=\"actions\"><button data-delete=\"${r.id}\" class=\"danger\">删除</button><button id=\"saveEdits\" class=\"primary\">保存修改</button></div><div class=\"divider\"></div><label class=\"check\"><input type=\"checkbox\" id=\"aiConsent\">将此资料的内容发送给 OpenAI，识别、转写并生成标题与摘要。</label><button id=\"analyze\" class=\"full\" ${!me?.aiEnabled?'disabled':''}>✦ ${r.kind==='audio'?'转文字并归纳':'识别内容并归纳'}${!me?.aiEnabled?' · 尚未启用':''}</button><button id=\"newReminder\" class=\"full\">安排跟进计划</button><p id=\"detailError\" class=\"error\" role=\"status\"></p>`:'<p class=\"muted\">真实资料启用 AI 后可生成这样的内容标题、摘要与主题。</p>'}`;\nif(!r.demo){$('saveEdits').onclick=async()=>{const b=$('saveEdits');b.disabled=true;try{await patch(id,{title:$('editTitle').value,text:$('editText').value,topic:$('editTopic').value,intent:$('editIntent').value});notify('已保存');openDetail(id)}catch(e){$('detailError').textContent=e.message;b.disabled=false}};$('analyze').onclick=async()=>{if(!$('aiConsent').checked){$('detailError').textContent='请先确认发送这份资料给 AI。';return}const b=$('analyze');b.disabled=true;b.textContent='正在识别与归纳…';try{await api('memories/'+id+'/analyze',{method:'POST'});await refresh();openDetail(id);notify('内容已整理，请核对识别结果')}catch(e){$('detailError').textContent=e.message;b.disabled=false;b.textContent='重试识别'}};$('newReminder').onclick=()=>reminder(r)}show('detail')}\nfunction reminder(r){const now=new Date(Date.now()+86400000);now.setMinutes(now.getMinutes()-now.getTimezoneOffset());$('detailbody').innerHTML=`<h3>${esc(r.title)}</h3><form id=\"reminderform\"><label class=\"field\">重要程度<select id=\"priority\"><option>普通</option><option>重要</option><option>优先处理</option></select></label><label class=\"field\">计划时间<input required id=\"when\" type=\"datetime-local\" value=\"${now.toISOString().slice(0,16)}\"></label><label class=\"field\">跟进频率<select id=\"frequency\"><option>仅一次</option><option>每天</option><option>每周</option></select></label><p class=\"aiNote\">计划会被保存。本版不发送系统通知，稍后可在行动中查看。</p><button class=\"primary full\">保存计划</button><p id=\"reminderError\" class=\"error\"></p></form>`;$('reminderform').onsubmit=async e=>{e.preventDefault();if(new Date($('when').value)<=new Date()){$('reminderError').textContent='请选择未来时间';return}try{await patch(r.id,{reminder:{when:$('when').value,priority:$('priority').value,frequency:$('frequency').value,status:'进行中'}});$('detail').close();openPanel('tasks');notify('计划已保存')}catch(e){$('reminderError').textContent=e.message}}}\nfunction deleteRecord(id){const r=get(id);if(!r||r.demo)return;show('confirm');$('confirmDelete').onclick=async()=>{$('confirmDelete').disabled=true;try{await patch(id,{deleted:true});$('confirm').close();$('detail').close();notify('已移到回收站，可随时恢复')}catch(e){notify(e.message)}finally{$('confirmDelete').disabled=false}}}\nfunction switchMode(next){if(recorder?.state==='recording'){notify('先停止录音，再切换输入方式');return}mode=next;document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));$('attachmentArea').hidden=mode==='text';$('recordArea').hidden=mode!=='audio';$('file').accept=mode==='image'?'image/png,image/jpeg,image/webp':'audio/*';$('filelabel').textContent=mode==='image'?'选择图片，或拖到这里':'选择已有录音，也可以直接录制';$('thought').placeholder=mode==='text'?'随手写点什么，也可以粘贴链接…':'给这份内容补充一点说明（可选）…';$('savehint').textContent=mode==='text'?'链接会被保存，只有点击时才打开。':'原始内容会先保存，识别可稍后进行。';clearAttachment()}\nfunction clearAttachment(){attachment=null;if(attachmentURL)URL.revokeObjectURL(attachmentURL);attachmentURL=null;$('attachmentPreview').innerHTML='';$('file').value=''}\nfunction setAttachment(file){if(file.size>10*1024*1024){notify('文件需小于 10 MB');return}const image=['image/png','image/jpeg','image/webp'].includes(file.type);const audio=/^(audio\\/|video\\/webm)/.test(file.type);if(!image&&!audio){notify('请选择 PNG、JPG、WebP 图片或音频');return}if(recorder?.state==='recording'){notify('请先停止录音');return}if(mode!==(image?'image':'audio'))switchMode(image?'image':'audio');clearAttachment();attachment=file;attachmentURL=URL.createObjectURL(file);$('attachmentPreview').innerHTML=(image?`<img src=\"${attachmentURL}\" alt=\"待保存图片\">`:`<audio controls src=\"${attachmentURL}\"></audio>`)+`<button id=\"removeFile\" class=\"smallbtn\">移除附件</button>`;$('removeFile').onclick=clearAttachment}\nasync function save(){if(saving)return;if(recorder?.state==='recording'){notify('请先停止录音并试听');return}const text=$('thought').value.trim();if(!text&&!attachment){notify('先写点内容，或添加图片、录音');return}if(!me){openAccount();return}saving=true;$('save').disabled=true;$('save').textContent='保存中…';const form=new FormData();form.set('text',text);if(attachment)form.set('file',attachment);try{const r=await api('memories',{method:'POST',body:form});$('thought').value='';clearAttachment();records.unshift(r);$('total').textContent=records.filter(x=>!x.deletedAt).length;renderSearch();if($('panel').open)renderPanel();notify('已收好，内容已保存到账号空间');openDetail(r.id)}catch(e){notify(e.message)}finally{saving=false;$('save').disabled=false;$('save').textContent='收好 ↗'}}\nasync function record(){if(recorder?.state==='recording'){recorder.stop();return}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){notify('当前浏览器不支持录音，可以上传已有音频文件');return}try{stream=await navigator.mediaDevices.getUserMedia({audio:true});const mime=['audio/webm','audio/mp4'].find(t=>MediaRecorder.isTypeSupported(t));recorder=new MediaRecorder(stream,mime?{mimeType:mime}:{});const parts=[];let seconds=0;recorder.ondataavailable=e=>{if(e.data.size)parts.push(e.data)};recorder.onstop=()=>{clearTimeout(recordTimer);clearInterval(recordClock);stream.getTracks().forEach(t=>t.stop());const type=recorder.mimeType;const file=new File(parts,'录音.'+(type.includes('mp4')?'m4a':'webm'),{type});recorder=null;$('record').textContent='● 重新录音';$('recordState').textContent='录音已停止，可试听后保存';setAttachment(file)};recorder.onerror=()=>{stream.getTracks().forEach(t=>t.stop());clearTimeout(recordTimer);clearInterval(recordClock);notify('录音中断，请重新尝试')};recorder.start();$('record').textContent='■ 停止录音';$('recordState').textContent='正在录音 0:00';recordClock=setInterval(()=>{seconds++;$('recordState').textContent=`正在录音 ${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`},1000);recordTimer=setTimeout(()=>{if(recorder?.state==='recording')recorder.stop()},120000)}catch{stream?.getTracks().forEach(t=>t.stop());notify('未获得麦克风权限，可在浏览器设置中允许，或上传录音')}}\nfunction openAccount(){$('accountbody').innerHTML=`<div class=\"accountcard\"><b>${me?'已登录 · 私人空间':'登录 / 首次使用'}</b><p>${me?esc(me.email):'首次通过 ChatGPT 登录后，即可使用账号空间。'}</p>${me?'<a href=\"/signout-with-chatgpt?return_to=%2F\" target=\"_top\">退出登录</a>':'<a class=\"signin\" href=\"/signin-with-chatgpt?return_to=%2F\" target=\"_top\">使用 ChatGPT 登录 / 首次开通</a>'}<p>当前使用 ChatGPT 账号。独立邮箱注册、密码找回尚未接入；这个私有原型仅对拥有访问权限的账号开放。</p></div><div class=\"accountcard\"><b>AI 识别与问答 · ${me?.aiEnabled?'已配置':'尚未配置'}</b><p>图片：内容标题、文字转录、聊天话题与摘要。录音：转文字并归纳。问答：依据保存的文字资料回答并标注来源。</p><p>需要服务端模型密钥才能使用，不要把密钥粘贴进记忆框。启用后，每次处理前可确认发送的资料。</p></div><div class=\"accountcard\"><b>数据与链接</b><p>文字和文件按账号隔离保存。删除先移入回收站，可恢复。网盘和商品链接按原样保存，不自动访问、解析或购买。</p><button id=\"export\" ${!me?'disabled':''}>导出文字资料与链接</button></div>`;$('export').onclick=()=>{const blob=new Blob([JSON.stringify(records,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='拾忆-文字资料.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);notify('已导出文字与链接；原始附件不包含在此文件中')};show('accountDialog')}\nasync function ask(q,ids){$('paneltitle').textContent='问问这些记忆';$('panelbody').innerHTML=`<p>${esc(q)}</p><p class=\"muted\">${ids.length?'使用匹配的最多 20 条资料':'使用最近最多 40 条资料的文字内容'}回答，附上来源。未识别图片不包含在可理解内容中。</p><label class=\"check\"><input id=\"askConsent\" type=\"checkbox\">同意将这些资料的文字内容发送给 OpenAI 进行汇总。</label><button id=\"askConfirm\" class=\"primary full\" ${!me?.aiEnabled?'disabled':''}>${me?.aiEnabled?'开始归纳':'AI 尚未启用'}</button><div id=\"answer\" class=\"answer\"></div><div id=\"sources\"></div>`;show('panel');$('askConfirm').onclick=async()=>{if(!$('askConsent').checked){notify('请先确认使用这些资料');return}$('askConfirm').disabled=true;$('answer').textContent='正在阅读资料…';try{const r=await api('ask',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({query:q,ids})});$('answer').textContent=r.answer;$('sources').innerHTML=r.sources.map(s=>`<button class=\"related\" data-open=\"${s.id}\">[${s.number}] ${esc(s.title)}</button>`).join('')}catch(e){$('answer').textContent=e.message}finally{$('askConfirm').disabled=false}}}\ndocument.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.dataset.view)openPanel(b.dataset.view);if(b.dataset.close)$(b.dataset.close).close();if(b.dataset.open)openDetail(b.dataset.open);if(b.dataset.delete)deleteRecord(b.dataset.delete);if(b.dataset.restore){await patch(b.dataset.restore,{deleted:false});notify('已恢复资料')}if(b.dataset.mode)switchMode(b.dataset.mode);if(b.dataset.filter){filter=b.dataset.filter;renderPanel()}if(b.dataset.topic){view='library';panelQuery=b.dataset.topic;filter='全部';renderPanel()}if('copy'in b.dataset){await navigator.clipboard.writeText(get(b.dataset.record).links[Number(b.dataset.copy)]);notify('链接已复制')}if(b.dataset.task){const r=get(b.dataset.task);let rem={...r.reminder};if(b.dataset.status==='cancel')rem=null;else if(b.dataset.status==='delay'){const d=new Date(rem.when);d.setDate(d.getDate()+1);d.setMinutes(d.getMinutes()-d.getTimezoneOffset());rem.when=d.toISOString().slice(0,16)}else rem.status=b.dataset.status;await patch(r.id,{reminder:rem});notify('行动计划已更新')}}catch(e){notify(e.message)}});\n$('save').onclick=save;$('file').onchange=e=>{if(e.target.files[0])setAttachment(e.target.files[0])};$('filepick').ondragover=e=>e.preventDefault();$('filepick').ondrop=e=>{e.preventDefault();if(e.dataTransfer.files[0])setAttachment(e.dataTransfer.files[0])};$('thought').onpaste=e=>{if(e.clipboardData.files.length){e.preventDefault();setAttachment(e.clipboardData.files[0])}};$('record').onclick=record;$('search').oninput=renderSearch;$('account').onclick=openAccount;$('aboutai').onclick=openAccount;$('trydemo').onclick=()=>openPanel('demo');$('home').onclick=()=>{document.querySelectorAll('dialog[open]').forEach(d=>d.close());$('search').value='';renderSearch();$('thought').focus()};document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();document.querySelectorAll('dialog[open]').forEach(d=>d.close());$('search').focus()}});window.addEventListener('pagehide',()=>{stream?.getTracks().forEach(t=>t.stop());clearTimeout(recordTimer);clearInterval(recordClock)});init();\nif(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'search_saved_memories',description:'Search saved, non-deleted memory text by keyword and show results. Does not call AI or search unread images.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(typeof input?.query!=='string')throw new Error('query must be a string');$('search').value=input.query;renderSearch();return{items:records.filter(r=>!r.deletedAt&&match(r,input.query)).map(r=>({id:r.id,title:r.title}))}}})).catch(()=>{})}catch{}}\n"}};
